		return;
	}

	$.set(errorMessage, null);
	$.set(isLoading, true);
	$.set(address, null);
	$.set(feeSats, 0);

	try {
		let prepareRequest = { paymentMethod: $.get(paymentMethod) };

		if (amountSats > 0 && $.get(paymentMethod) !== "bolt12Offer") {
			if ($.get(selectedAsset) === "USDt" && $.get(paymentMethod) === "liquidAddress") {
				prepareRequest.amount = {
					type: "asset",
					assetId: getAssetId("USDT"),
					payerAmount: $.get(amount)
				};
			} else {
				prepareRequest.amount = { type: "bitcoin", payerAmountSat: amountSats };
			}
		}

		const prepareResponse = await prepareReceivePayment(prepareRequest);

		console.log("prepareResponse", prepareResponse);

		const receiveResponse = await receivePayment({
			prepareResponse,
			description: $.get(description) || getDefaultDescription()
		});

		console.log("receiveResponse", receiveResponse);
		$.set(address, receiveResponse.destination, true);
		$.set(feeSats, prepareResponse.feesSat || 0, true);
	} catch(error) {
		console.error("Error generating payment request:", error);
		$.set(errorMessage, error instanceof Error ? error.message : "Failed to generate payment request. Please try again.", true);
	} finally {
		$.set(isLoading, false);
	}
}

